  2	/**
  3	 * Interactive local development environment setup script.
  4	 *
  5	 * Prompts the user for database and UI settings, generates
  6	 * `test-db-config.php` and `test-ui-config.php` from their `.dist.php`
  7	 * templates, creates the database if it does not exist, imports the
  8	 * base schema, and then runs `composer seed-tests` to seed system users.
  9	 *
 10	 * Usage:
 11	 *   php tools/setup-local.php
 12	 *   composer setup
 13	 *
 14	 * The script is idempotent: re-running it reads existing config values as
 15	 * defaults so the user only needs to change what has actually changed.
 16	 *
 17	 * @package Application
 18	 * @subpackage Tools
 19	 */
 20	
 21	declare(strict_types=1);
 22	
 23	// ============================================================================
 24	// Bootstrap — shared CLI utilities
 25	// ============================================================================
 26	
 27	require_once __DIR__ . '/include/cli-utilities.php';
 28	
 29	// ============================================================================
 30	// Path constants
 31	// ============================================================================
 32	
 33	const SETUP_ROOT       = __DIR__ . '/..';
 34	const SETUP_CONFIG_DIR = SETUP_ROOT . '/tests/application/config';
 35	
 36	const SETUP_TPL_DB  = SETUP_CONFIG_DIR . '/test-db-config.dist.php';
 37	const SETUP_TPL_UI  = SETUP_CONFIG_DIR . '/test-ui-config.dist.php';
 38	
 39	const SETUP_DB_CONFIG  = SETUP_CONFIG_DIR . '/test-db-config.php';
 40	const SETUP_UI_CONFIG  = SETUP_CONFIG_DIR . '/test-ui-config.php';
 41	
 42	const SETUP_SQL_SCHEMA = SETUP_ROOT . '/tests/sql/testsuite.sql';
 43	
 44	// ============================================================================
 45	// SIGINT handler — restore terminal echo if interrupted during password input
 46	// ============================================================================
 47	
 48	if (function_exists('pcntl_signal'))
 49	{
 50	    pcntl_signal(SIGINT, static function () : void {
 51	        shell_exec('stty echo 2>/dev/null');
 52	        writeln();
 53	        writeln(color('Setup interrupted.', 'yellow'));
 54	        exit(130);
 55	    });
 56	    pcntl_async_signals(true);
 57	}
 58	
 59	// ============================================================================
 60	// Helpers — existing config parsing (idempotency)
 61	// ============================================================================
 62	
 63	/**
 64	 * Extracts a PHP constant value from a config file's raw content.
 65	 *
 66	 * Handles three value shapes written by this script:
 67	 *   const NAME = 'some string';
 68	 *   const NAME = 123;           (bare integer)
 69	 *   const NAME = null;          (null literal)
 70	 *
 71	 * @param string $constant The constant name to search for.
 72	 * @param string $content  The raw PHP source of the config file.
 73	 * @return string The extracted value as a string, or '' when not found.
 74	 */
 75	function extractConstantValue(string $constant, string $content) : string
 76	{
 77	    // String value: const NAME = 'value';
 78	    if (preg_match('/const\s+' . preg_quote($constant, '/') . '\s*=\s*\'(.*?)\'\s*;/s', $content, $m))
 79	    {
 80	        return $m[1];
 81	    }
 82	
 83	    // Integer value: const NAME = 123;
 84	    if (preg_match('/const\s+' . preg_quote($constant, '/') . '\s*=\s*(\d+)\s*;/', $content, $m))
 85	    {
 86	        return $m[1];
 87	    }
 88	
 89	    // Null literal: const NAME = null;
 90	    if (preg_match('/const\s+' . preg_quote($constant, '/') . '\s*=\s*null\s*;/i', $content, $m))
 91	    {
 92	        return 'null';
 93	    }
 94	
 95	    return '';
 96	}
