115	// ----------------------------------------------------------------------------
116	// promptPassword
117	// ----------------------------------------------------------------------------
118	
119	if (!function_exists('promptPassword'))
120	{
121	    /**
122	     * Displays a prompt and reads a password from STDIN without echoing input.
123	     *
124	     * On Unix-like systems `stty -echo` is used to suppress character echo.
125	     * On Windows (or when stty is unavailable) input is read with echo visible
126	     * and a warning is displayed to the user.
127	     *
128	     * @param string $label   The label to display before the input cursor.
129	     * @param string $default The value to use when the user provides no input.
130	     * @return string The trimmed user input, or $default when input is empty.
131	     */
132	    function promptPassword(string $label, string $default = '') : string
133	    {
134	        // shell_exec returns null only when the function is disabled (e.g. php.ini
135	        // disable_functions). The DIRECTORY_SEPARATOR guard already excludes Windows;
136	        // the null-check provides a secondary guard for environments where shell_exec
137	        // itself is disabled. The stty exit status (via `; echo $?`) is discarded here
138	        // because the meaningful check is whether stty is actually available, which is
139	        // tested by calling it below — if it fails, the shell absorbs the error silently.
140	        $sttyAvailable = (DIRECTORY_SEPARATOR !== '\\')
141	            && (shell_exec('stty 2>/dev/null; echo $?') !== null);
142	
143	        if ($default !== '')
144	        {
145	            echo $label . ' [' . str_repeat('*', min(8, strlen($default))) . ']: ';
146	        }
147	        else
148	        {
149	            echo $label . ': ';
150	        }
151	
152	        if ($sttyAvailable)
153	        {
154	            shell_exec('stty -echo');
155	            $input = fgets(STDIN);
156	            shell_exec('stty echo');
157	            echo PHP_EOL;
158	        }
159	        else
160	        {
161	            writeln('(warning: password will be visible — stty not available)');
162	            $input = fgets(STDIN);
163	        }
164	
165	        if ($input === false)
166	        {
167	            return $default;
168	        }
169	
170	        $trimmed = trim($input);
171	
172	        if ($trimmed === '')
173	        {
174	            return $default;
175	        }
176	
177	        return $trimmed;
178	    }
179	}

